"src/core/dom.js":(require,exports)=>{
function node(html) {
  const t = document.createElement("template");
  t.innerHTML = html.trim();
  return t.content.firstElementChild;
}
function escapeHTML(value) {
  return String(value).replace(
    /[&<>"']/g,
    (c) =>
      ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[
        c
      ],
  );
}
function listen(target, type, handler, signal) {
  target.addEventListener(type, handler, { signal });
}
function bind(root, signal, handler) {
  listen(
    root,
    "click",
    (event) => {
      const button = event.target.closest("[data-action]");
      if (button && root.contains(button))
        handler(button.dataset.action, button, event);
    },
    signal,
  );
}

Object.assign(exports,{node,escapeHTML,listen,bind});
},
"src/core/store.js":(require,exports)=>{
const { getThemesById } = require("src/data/catalog.js");
function createStore(){
 let preferences={},theme="galaxy";
 try{const saved=JSON.parse(localStorage.getItem("snx.studio.v7")||"{}");if(saved&&typeof saved==="object"&&!Array.isArray(saved))preferences=saved;}catch{}
 function get(){const t=getThemesById()[theme]||getThemesById().galaxy,p=preferences[theme]||{};
  const defaults=t.defaultIcons.length?t.defaultIcons:t.icons.slice(0,12).map(i=>i.id);
  const activeWidget=t.widgets.find(w=>w.id===p.widget);
  return Object.freeze({theme,wallpaper:t.wallpapers.some(w=>w.id===p.wallpaper)?p.wallpaper:t.wallpapers[0]?.id||null,
   iconSlots:Array.from({length:12},(_,i)=>t.icons.some(x=>x.id===p.iconSlots?.[i])?p.iconSlots[i]:defaults[i%defaults.length]),
   widget:activeWidget?activeWidget.id:null,
   widgetSize:["small","medium","large"].includes(p.widgetSize)?p.widgetSize:(activeWidget?.format||"medium"),
   selectedSlot:Number.isInteger(p.selectedSlot)&&p.selectedSlot>=0&&p.selectedSlot<12?p.selectedSlot:0});
 }
 return {get,set(patch){if(getThemesById()[patch.theme])theme=patch.theme;preferences[theme]={...get(),...patch};const s=get();preferences[theme]={...s};try{localStorage.setItem("snx.studio.v7",JSON.stringify(preferences));}catch{}return s;}};
}

Object.assign(exports,{createStore});
},
"src/data/catalog.js":(require,exports)=>{
const {themes: packs} = require("src/data/packs.js");
const {loadCustomThemes} = require("src/data/customThemes.js");
function build(){const custom=loadCustomThemes();const list=[...packs,...custom];return {list,byId:Object.fromEntries(list.map(t=>[t.id,t]))};}
let cache=build();
function refreshThemes(){cache=build();return cache.list;}
function getThemes(){return cache.list;}
function getThemesById(){return cache.byId;}
const routes=[{id:"home",label:"Accueil"},{id:"collections",label:"Collections"},{id:"studio",label:"Studio"},{id:"mine",label:"Pour moi"}];
const money=n=>new Intl.NumberFormat("fr-FR",{style:"currency",currency:"EUR"}).format(n);
const formats=[{id:"small",name:"Small"},{id:"medium",name:"Medium"},{id:"large",name:"Large"}];
const commerce={
 mode:"demo",
 contactEmail:"jphkkrysv@gmail.com",
 etsyUrl:"https://www.etsy.com/shop/SoftGlowIcons",
 legalOwner:"SnX-StuDiO KIM",
 legalAddress:"Montpellier, France"
};

Object.assign(exports,{refreshThemes,getThemes,getThemesById,routes,money,formats,commerce});
},
